    if (histProof === 'tg' && !(p && p.telegram)) return false;
    if (histProof === 'real' && n._st.state !== 'verified') return false;
    if (histProof === 'dead' && n._st.state !== 'dead') return false;
    if (histProof === 'unknown' && n._st.state !== 'unknown') return false;
    if (histProof === 'unchecked' && n._st.state !== 'unchecked' && n._st.state !== 'none') return false;
    if (q && !String(n.u).toLowerCase().includes(q)) return false;
