    const tg = st.state !== 'none' && st.at ? ' · ' + agoText(st.at) : '';
    return `<a class="hrp s-${st.state}" href="https://www.instagram.com/${encodeURIComponent(n.u)}/" target="_blank" rel="noopener" title="${esc(st.label)}${esc(st.why ? ' · ' + st.why : '')}${esc(tg)}">${icon} @${esc(n.u)}</a>`;
