  // вытесняет прежние «✖ ошибка / ❔ пропущен» этого же ника (просьба юзера). Джобы,
  // у которых ник не опознаётся (легаси без username и без tg-ссылки), не схлопаем —
  // сгруппировать их нельзя, а молча выбросить — значит потерять запись.
  const seenU = new Set();
