// Клик по уведомлению в шторке: модалка истории открывается на нужной вкладке
// И РАСКРЫВАЕТ именно тот предмет: разбор профиля → «Автоанализ» с текстом
// разбора, проверка TG → «Ревизия TG» с развёрнутым «▸ кто» того прогона,
// нащел в Instagram → карточка аккаунта в «Аккаунтах». Фильтры, способные
// проглотить нужную строку, сбрасываются и в состоянии, и в контролах — иначе
// переход из уведомления иногда показывал бы пустой список.
function histJumpTo(kind, username) {
  const u = String(username || '');
  const ul = u.toLowerCase();
  if (!u) return;
  histRunQuery = ''; const qEl = $('hrQ'); if (qEl) qEl.value = '';
  histDateFrom = ''; histDateTo = '';
  const dfEl = $('hrDateFrom'); const dtEl = $('hrDateTo');
  if (dfEl) dfEl.value = ''; if (dtEl) dtEl.value = '';
  histProof = ''; const psEl = $('histProofSel'); if (psEl) psEl.value = '';
  histPaaStatus = 'all'; document.querySelectorAll('#hfPaaStatus button').forEach((x) => x.classList.toggle('is-on', x.dataset.s === 'all'));
  histExpand.paa = ''; histExpand.rev = '';
  if (kind === 'paa') {
    // самый свежий джоб этого ника (gatherPaaJobs уже по убыванию startedAt);
    // бегущий раскрывать нечем — отчёт появится только в финале
    const job = gatherPaaJobs(lastAll).find((j) => paaJobUser(j) === ul);
    if (job && job.status !== 'running') histExpand.paa = String(job.id);
  } else if (kind === 'rev') {
    // прогон ревизии, в котором этот ник реально проверялся (sample — имена того
    // заезда); если не нашли — раскрываем самый свежий, НО не когда ревизия ещё
    // идёт: её записи в истории нет до финала, и раскрытый старый заезд врал бы
    const runs = gatherTgrevRuns(lastAll);
    let run = runs.find((r) => {
      const s = r.sample || {};
      return (s.real || []).concat(s.dead || [], s.unknown || [])
        .some((n) => String(n).toLowerCase() === ul);
    });
    if (!run && !rev.running) run = runs[0];
    if (run && run.id) histExpand.rev = String(run.id);
  } else {
    // карточка аккаунта: ключ Set — ник в исходном регистре, как в data-acc
    histAccFilter = { q: '', folMin: '', folMax: '', tg: 'all', fresh: false, niche: '', gender: 'all', color: 'all', wrote: 'all' };
    ['hfQ', 'hfFolMin', 'hfFolMax'].forEach((id) => { const el = $(id); if (el) el.value = ''; });
    const frEl = $('hfFresh'); if (frEl) frEl.checked = false;
    [['#hfTg', 'tg'], ['#hfGender', 'g'], ['#hfColor', 'c'], ['#hfWrote', 'w'], ['#hfWrotePaa', 'w']].forEach(([sel, attr]) => {
      document.querySelectorAll(sel + ' button').forEach((b) => b.classList.toggle('is-on', b.dataset[attr] === 'all'));
    });
    // сортировка «свежие сверху»: цель точно не уедет за кап лимита в 500 строк
    histSortAcc = 'new';
    document.querySelectorAll('#histSortAcc button').forEach((x) => x.classList.toggle('is-on', x.dataset.sort === 'new'));
    histOpenAcc.add(u);
  }
  if (!historyOpen) openHistory();
  selectHistTab(kind === 'paa' ? 'paa' : kind === 'rev' ? 'tgrev' : 'accounts');
  // selectHistTab рендерит синхронно — скроллим к строке следующим кадром
  requestAnimationFrame(() => {
    const list = $('histList');
    if (!list) return;
    let row = null;
    if (kind === 'paa') row = list.querySelector('.hr-paa.is-open');
    else if (kind === 'rev') row = list.querySelector('.hr-tgrev.is-open');
    else row = list.querySelector('.hr-acc[data-acc="' + CSS.escape(u) + '"]');
    if (row) { try { row.scrollIntoView({ block: 'center', behavior: 'smooth' }); } catch (_) {} }
  });
}
