// «📋 скопировать» разбора: текст из кэша, флэш на кнопке — визуальное «готово».
$('histList').addEventListener('click', (e) => {
  const b = e.target.closest('.hr-copy');
  if (!b) return;
  const txt = paaReportCache.get(b.dataset.key || '') || '';
  if (!txt) return;
  const done = () => { const o = b.textContent; b.textContent = '✅ скопировано'; setTimeout(() => { b.textContent = o; }, 1400); };
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(txt).then(done, () => { b.textContent = '✖ не вышло'; setTimeout(done, 1400); });
  } else {
    try {
      const ta = document.createElement('textarea'); ta.value = txt; document.body.appendChild(ta); ta.select();
      document.execCommand('copy'); document.body.removeChild(ta); done();
    } catch (_) {}
  }
});
// 🚩 Метка профиля в автоанализе: клик по флажку зажигает/гасит оранжевую подсветку
