// onChanged донесёт их до других вкладок дашборда.
$('histList').addEventListener('click', (e) => {
  const b = e.target.closest('.hr-mark');
  if (!b) return;
  const u = String(b.dataset.mark || '').toLowerCase();
  if (!u) return;
  (async () => {
    try {
      const d = await chrome.storage.local.get(PAA_MARKS_KEY);
      const m = (d && d[PAA_MARKS_KEY] && typeof d[PAA_MARKS_KEY] === 'object') ? Object.assign({}, d[PAA_MARKS_KEY]) : {};
      if (m[u]) delete m[u]; else m[u] = Date.now();
      await chrome.storage.local.set({ [PAA_MARKS_KEY]: m });
      lastAll[PAA_MARKS_KEY] = m; // не ждём onChanged — перерисовка сразу
      renderHistory();
    } catch (_) {}
  })();
});
