  const factors = [
    { label: 'Скорость', slabel: 'Скор', v: fRate, txt: rate + '/ч', color: '#ef4444', vert: true },
    { label: 'Пауза', slabel: 'Пау', v: fPause, txt: avgPause ? (Math.round(avgPause / 100) / 10) + 'с' : '—', color: '#f97316', vert: true },
    { label: 'Окна', slabel: 'Окн', v: fWin, txt: String(wins), color: '#a855f7', vert: true },
    { label: 'Пик', slabel: 'Пик', v: fBurst, txt: burst5 + '/5м', color: '#eab308', vert: true },
  ];
  const reasons = alarms.filter((a) => a.sev >= 2).map((a) => a.name.toLowerCase());
  // «Жар сессии»: счёт подпрыгивает мгновенно, но остывает медленно (PEAK_TAU) — чтобы
  // «выключил авточек» не ронял шкалу с 50 до 5 за секунды, когда аккаунт ещё горячий
  // и «тя забанит через пару проверок». Пик держится и плавно гаснет ~20 минут.
  const PEAK_TAU = 20 * 60000;
